import { useState, useEffect, useContext } from "react";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";
import { useNavigate } from "react-router-dom";

export default function AdminDashboard() {
  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [reportHash, setReportHash] = useState("");
  const [results, setResults] = useState({});
  const [winners, setWinners] = useState({});

  const { logout, token, user } = useContext(AuthContext);
  const navigate = useNavigate();

  // ---------------- Unified error handler ----------------
  const handleApiError = (err) => {
    console.error(err);
    if (err.response?.status === 401) {
      logout();
      navigate("/login");
    } else {
      alert(err.response?.data?.error || err.message);
    }
  };

  // ---------------- Backend API calls ----------------
  const fetchVotingState = async () => {
    try {
      const res = await api.get("/admin/voting-state");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchPendingUsers = async () => {
    try {
      const res = await api.get("/admin/pending-users");
      setPendingUsers(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchCandidates = async () => {
    try {
      const res = await api.get("/admin/candidates");
      setCandidates(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchLogs = async () => {
    try {
      const res = await api.get("/admin/logs");
      setLogs(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const toggleVoting = async () => {
    try {
      const res = await api.post("/admin/toggle-voting");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      handleApiError(err);
    }
  };

  const approveUser = async (id) => {
    try {
      await api.post(`/admin/approve-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      handleApiError(err);
    }
  };

  const rejectUser = async (id) => {
    try {
      await api.post(`/admin/reject-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      handleApiError(err);
    }
  };

  const generateReport = async () => {
    try {
      const res = await api.post("/admin/generate-report");
      setReportHash(res.data.hash);
    } catch (err) {
      handleApiError(err);
    }
  };

  const deleteCandidate = async (id) => {
    if (!window.confirm("Delete this candidate?")) return;
    try {
      await api.delete(`/admin/candidates/${id}`);
      fetchCandidates();
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchResults = async () => {
    try {
      const res = await api.get("/admin/results");
      setResults(res.data.positionResults);
      setWinners(res.data.winners);
    } catch (err) {
      handleApiError(err);
    }
  };

  // ---------------- Initial load ----------------
  useEffect(() => {
    if (!token) {
      navigate("/login");
      return;
    }

    const init = async () => {
      await fetchVotingState();
      await fetchPendingUsers();
      await fetchCandidates();
      await fetchLogs();
      await fetchResults();
    };
    init();
  }, [token]);

  // ---------------- Actions as cards ----------------
  const actions = [
    {
      title: "Voting Status",
      desc: `Voting is currently ${votingOpen ? "Open" : "Closed"}.`,
      component: (
        <button
          onClick={toggleVoting}
          className={`px-6 py-2 rounded-lg font-semibold text-white transition ${votingOpen ? "bg-red-600 hover:bg-red-700" : "bg-green-600 hover:bg-green-700"}`}
        >
          {votingOpen ? "Close Voting" : "Open Voting"}
        </button>
      ),
    },
    {
      title: "Pending Users",
      desc: "Approve or reject pending voter registrations.",
      component: pendingUsers.length === 0 ? (
        <p className="text-gray-500 italic">No pending users.</p>
      ) : (
        <ul className="space-y-2">
          {pendingUsers.map((u) => (
            <li key={u.id} className="flex justify-between items-center border-b pb-1">
              <span>{u.name} ({u.studentNumber})</span>
              <div className="space-x-2">
                <button onClick={() => approveUser(u.id)} className="bg-green-600 text-white px-3 py-1 rounded hover:bg-green-700">Approve</button>
                <button onClick={() => rejectUser(u.id)} className="bg-red-600 text-white px-3 py-1 rounded hover:bg-red-700">Reject</button>
              </div>
            </li>
          ))}
        </ul>
      ),
    },
    {
      title: "Candidates",
      desc: "Manage candidate applications.",
      component: candidates.length === 0 ? (
        <p className="text-gray-500 italic">No candidates yet.</p>
      ) : (
        <ul className="space-y-2">
          {candidates.map((c) => (
            <li key={c.id} className="flex justify-between items-center border-b pb-1">
              <span>{c.name} - {c.position}</span>
              <button onClick={() => deleteCandidate(c.id)} className="bg-red-600 text-white px-3 py-1 rounded hover:bg-red-700">Delete</button>
            </li>
          ))}
        </ul>
      ),
    },
    {
      title: "System Logs",
      desc: "Recent admin activity.",
      component: logs.length === 0 ? (
        <p className="text-gray-500 italic">No logs available.</p>
      ) : (
        <ul className="space-y-1 max-h-40 overflow-y-auto text-sm">
          {logs.map((log) => (
            <li key={log.id} className="flex justify-between">
              <span>{log.action}</span>
              <span className="text-gray-400">{new Date(log.createdAt).toLocaleString()}</span>
            </li>
          ))}
        </ul>
      ),
    },
    {
      title: "Results",
      desc: "Live election results.",
      component: Object.keys(results).length === 0 ? (
        <p className="text-gray-500 italic">No results yet.</p>
      ) : (
        Object.keys(results).map((pos) => (
          <div key={pos} className="mb-2">
            <h3 className="font-medium">{pos}</h3>
            <ul className="pl-4 text-sm">
              {results[pos].map((c) => (
                <li key={c.id}>
                  {c.name} - {c.votes} votes {winners[pos]?.id === c.id && <span className="text-green-600 font-semibold">(Winner)</span>}
                </li>
              ))}
            </ul>
          </div>
        ))
      ),
    },
    {
      title: "Reports",
      desc: "Generate a cryptographic election report.",
      component: (
        <div>
          <button
            onClick={generateReport}
            className="bg-blue-600 text-white px-5 py-2 rounded-lg hover:bg-blue-700 transition"
          >
            Generate Final Report
          </button>
          {reportHash && (
            <p className="mt-2 text-gray-600 text-sm">
              Hash: <span className="font-mono">{reportHash}</span>
            </p>
          )}
        </div>
      ),
    },
  ];

  // ---------------- JSX ----------------
  return (
    <div style={{ minHeight: "100vh", backgroundColor: "#f4f6f8", padding: "40px", fontFamily: "Arial, sans-serif" }}>
      <div style={{ maxWidth: "1200px", margin: "0 auto" }}>

        {/* Header */}
        <header style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "40px",
          backgroundColor: "#fff",
          padding: "15px 25px",
          borderRadius: "12px",
          boxShadow: "0 4px 12px rgba(0,0,0,0.08)"
        }}>
          <div style={{ display: "flex", alignItems: "center", gap: "15px" }}>
            <img src="/logo.png" alt="iVote Logo" style={{ height: "50px" }} />
            <div>
              <h1 style={{ fontSize: "1.8rem", color: "#007bff", margin: 0 }}>
                Welcome, {user?.name || "Admin"}
              </h1>
              <p style={{ margin: 0, color: "#555", fontSize: "0.9rem" }}>Admin Dashboard</p>
            </div>
          </div>
          <button 
            onClick={() => { logout(); navigate("/login"); }}
            style={{
              padding: "8px 16px",
              backgroundColor: "#ff4d4f",
              color: "#fff",
              border: "none",
              borderRadius: "8px",
              fontWeight: "bold",
              cursor: "pointer",
              transition: "background 0.2s"
            }}
            onMouseEnter={e => e.currentTarget.style.backgroundColor = "#d9363e"}
            onMouseLeave={e => e.currentTarget.style.backgroundColor = "#ff4d4f"}
          >
            Logout
          </button>
        </header>

        {/* Action Cards */}
        <div style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))",
          gap: "25px"
        }}>
          {actions.map((a, i) => (
            <div
              key={i}
              style={{
                padding: "25px",
                borderRadius: "12px",
                border: "1px solid #e0e6ed",
                background: "#fff",
                boxShadow: "0 2px 6px rgba(0,0,0,0.05)",
                transition: "all 0.2s ease-in-out"
              }}
              onMouseEnter={(e) => e.currentTarget.style.boxShadow = "0 6px 16px rgba(0,0,0,0.12)"}
              onMouseLeave={(e) => e.currentTarget.style.boxShadow = "0 2px 6px rgba(0,0,0,0.05)"}
            >
              <h2 style={{ fontSize: "1.25rem", color: "#007bff", marginBottom: "10px" }}>{a.title}</h2>
              <p style={{ fontSize: "0.95rem", color: "#555", marginBottom: "15px" }}>{a.desc}</p>
              {a.component}
            </div>
          ))}
        </div>

      </div>
    </div>
  );
}
